    public const string Js = """
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token='',catalog=null,projects=[],project=null,selectedNodeId=null,selectedRouteId=null,selectedBeat=0,saveTimer=null,saving=false,dirty=false,compiledJson='',rehearsalSteps=[],liveNodeId=null,runtimeTimer=null;
async function api(url,opt={},retry=true){let r=await fetch(url,{cache:'no-store',...opt,headers:{'Content-Type':'application/json',...(token?{'X-Workbench-Token':token}:{}),...(opt.headers||{})}}),t=await r.text(),d;try{d=t?JSON.parse(t):{error:`http_${r.status}`}}catch{d={error:`http_${r.status}`,detail:t||'Empty response'}}if(r.status===403&&retry&&!url.endsWith('/security')){token=(await api('/api/v1/workbench/security',{},false)).browser_token;return api(url,opt,false)}if(!r.ok)throw{...d,status:r.status};return d}
function status(title,detail,bad=false){$('#status-title').textContent=title;$('#status-detail').textContent=detail||'';$('.save-state').classList.toggle('bad',bad)}
function saveState(label,kind=''){$('#save-label').textContent=label;$('.save-state').className='save-state '+kind;$('#revision').textContent=project?`r${project.revision}`:''}
function stable(v,fallback='item'){let x=String(v||fallback).toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'');return(x||fallback).slice(0,64)}
function clone(v){return JSON.parse(JSON.stringify(v))}
async function boot(){token=(await api('/api/v1/workbench/security')).browser_token;catalog=await api('/api/v2/quest-studio/catalog');fillCatalog();bind();await loadProjects();pollRuntime();}
function fillCatalog(){$('#template').innerHTML=catalog.templates.map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('');let eo=catalog.events.map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('');$('#route-event').innerHTML=eo;$('#manual-event').innerHTML=eo;$('#new-action-type').innerHTML=catalog.actions.map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('');$('#scenario').innerHTML='<option value="">Choose a scenario</option>'+catalog.scenarios.map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('');simpleKinds=Object.fromEntries((catalog.simple_triggers||[]).map(x=>[x.id,{event:x.event_name,target:x.target??null,label:x.label,instruction:x.instruction}]));$('#beat-kind').innerHTML=(catalog.simple_triggers||[]).map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('');$('#beat-palette').innerHTML='<strong>Add the next beat</strong>'+(catalog.simple_triggers||[]).map(x=>`<button data-add-beat="${x.id}" class="${x.id==='wait'?'quiet':''}">${esc(x.label)}</button>`).join('');$('#event-tray').innerHTML=(catalog.simple_triggers||[]).filter(x=>x.id!=='wait').map(x=>`<button class="event-chip" data-event="${x.event_name}" data-target="${x.target||''}">${esc(x.label)}</button>`).join('')}
async function loadProjects(preferred){let d=await api('/api/v2/quest-studio/projects');projects=d.projects||[];renderLibrary();let target=preferred||project?.project_id||projects[0]?.project_id;if(target)await openProject(target);else{project=null;renderAll()}}
function renderLibrary(){$('#project-list').innerHTML=projects.length?projects.map(p=>`<button class="project-button ${project?.project_id===p.project_id?'active':''}" data-project="${p.project_id}"><strong>${esc(p.title)}</strong><span>${esc(p.version)} · ${p.node_count} nodes</span></button>`).join(''):'<div class="empty">No projects yet.</div>'}
async function openProject(id){if(dirty)await saveNow();project=await api('/api/v2/quest-studio/projects/'+encodeURIComponent(id));selectedNodeId=project.entry_node_id;selectedRouteId=project.nodes.find(x=>x.id===selectedNodeId)?.routes?.[0]?.id||null;selectedBeat=0;dirty=false;compiledJson='';rehearsalSteps=[];saveState('Saved');renderAll();await refreshRuntime()}
let simpleKinds={};
function kindFor(r){return Object.keys(simpleKinds).find(k=>simpleKinds[k].event===r.event&&(simpleKinds[k].target??null)===(r.target??null))||null}
