  $('#node-id').onchange=e=>{let n=node(),old=n.id,next=stable(e.target.value,'node');if(project.nodes.some(x=>x!==n&&x.id===next)){status('Node ID already exists',next,true);renderInspector();return}n.id=next;if(project.entry_node_id===old)project.entry_node_id=next;for(let x of project.nodes)for(let r of x.routes)if(r.destination_node_id===old)r.destination_node_id=next;selectedNodeId=next;changed()};$('#node-label').oninput=e=>{node().label=e.target.value;changed()};
