  $('#action-list').oninput=e=>{let card=e.target.closest('[data-action]');if(!card)return;let a=route().actions[Number(card.dataset.action)],field=e.target.dataset.field;if(!field)return;a[field]=e.target.type==='number'?Number(e.target.value):e.target.value;changed(false)};$('#action-list').onchange=e=>{let card=e.target.closest('[data-action]');if(!card)return;let a=route().actions[Number(card.dataset.action)],field=e.target.dataset.field;if(field){a[field]=e.target.type==='number'?Number(e.target.value):e.target.value;if(field==='kind'){let defs=catalog.actions.find(x=>x.id==='spawn').prefabs;a.prefab=defs[a.kind][0]}changed()}};$('#action-list').onclick=e=>{let b=e.target.closest('.remove-action');if(!b)return;let i=Number(b.closest('[data-action]').dataset.action);route().actions.splice(i,1);changed()};
