  $('#validate-project').onclick=()=>certify(false);$('#certify-project').onclick=()=>certify(true);$('#publish-project').onclick=publish;$('#copy-json').onclick=async()=>{if(!compiledJson)await certify(false);await navigator.clipboard.writeText(compiledJson);status('JSON copied','Certified Runtime document copied to clipboard.')};$('#download-json').onclick=async()=>{if(!compiledJson)await certify(false);let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([compiledJson],{type:'application/json'}));a.download=`${project.experience_id}.json`;a.click();URL.revokeObjectURL(a.href)};
